-- ============================================================
-- Migration Neon PostgreSQL pour le portfolio Abderrahim Talibi
-- A executer dans Neon SQL Editor (une seule fois).
-- ============================================================

CREATE TABLE IF NOT EXISTS admins (
  id SERIAL PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  salt TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS admin_sessions (
  id TEXT PRIMARY KEY,
  token TEXT NOT NULL UNIQUE,
  email TEXT NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS portfolio_content (
  id TEXT PRIMARY KEY,
  content JSONB NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS contact_messages (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  subject TEXT NOT NULL,
  message TEXT NOT NULL,
  is_read BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO portfolio_content (id, content, updated_at)
VALUES ('main', {"projects": [{"id": "proj-presenceqr", "title": {"en": "Pr\u00e9senceQR", "fr": "Pr\u00e9senceQR", "de": "Pr\u00e9senceQR", "ar": "Pr\u00e9senceQR"}, "description": {"en": "QR-code attendance platform: Django REST Framework API, real-time tracking over WebSockets, PostgreSQL, proximity validation, Excel session reports and a Flutter mobile app.", "fr": "Plateforme de pr\u00e9sence par QR code : API Django REST Framework, suivi temps r\u00e9el via WebSockets, PostgreSQL, validation par proximit\u00e9, rapports de session Excel et application mobile Flutter.", "de": "QR-Code-Anwesenheitsplattform: Django-REST-API, Echtzeit-Tracking \u00fcber WebSockets, PostgreSQL, N\u00e4herungsvalidierung, Excel-Berichte und Flutter-App.", "ar": "\u0645\u0646\u0635\u0629 \u062d\u0636\u0648\u0631 \u0639\u0628\u0631 \u0631\u0645\u0632 QR: \u0648\u0627\u062c\u0647\u0629 Django REST\u060c \u062a\u062a\u0628\u0639 \u0641\u0648\u0631\u064a \u0639\u0628\u0631 WebSockets\u060c PostgreSQL\u060c \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0642\u0631\u0628\u060c \u062a\u0642\u0627\u0631\u064a\u0631 Excel \u0648\u062a\u0637\u0628\u064a\u0642 Flutter."}, "tags": ["Django", "DRF", "PostgreSQL", "WebSockets", "Flutter"], "image": "/assets/images/project_attendance_3d_light_1793556805155.jpg", "github": "https://github.com/abdertalibi-gif/Qr_code_pfe-", "demo": "", "published": true, "featured": true, "order": 1, "createdAt": "2026-11-21T11:56:43.949Z", "updatedAt": "2026-11-21T11:56:43.949Z"}, {"id": "proj-agent-auditor", "title": {"en": "Agent Readiness Auditor", "fr": "Agent Readiness Auditor", "de": "Agent Readiness Auditor", "ar": "Agent Readiness Auditor"}, "description": {"en": "SaaS that audits how ready a website is to be discovered and understood by AI agents: safe crawler, ~60 deterministic checks, weighted score across 8 categories, PDF report and optional grounded LLM explanations.", "fr": "SaaS qui \u00e9value la capacit\u00e9 d''un site \u00e0 \u00eatre d\u00e9couvert et compris par des agents IA : crawler s\u00e9curis\u00e9, ~60 contr\u00f4les d\u00e9terministes, score pond\u00e9r\u00e9 sur 8 cat\u00e9gories, rapport PDF et explications LLM optionnelles.", "de": "SaaS, das bewertet, wie gut eine Website von KI-Agenten erkannt und verstanden wird: sicherer Crawler, ~60 deterministische Pr\u00fcfungen, gewichtete Bewertung \u00fcber 8 Kategorien, PDF-Bericht und optionale LLM-Erkl\u00e4rungen.", "ar": "\u0645\u0646\u0635\u0629 SaaS \u062a\u0642\u064a\u0651\u0645 \u0645\u062f\u0649 \u062c\u0627\u0647\u0632\u064a\u0629 \u0645\u0648\u0642\u0639 \u0648\u064a\u0628 \u0644\u0623\u0646 \u062a\u0641\u0647\u0645\u0647 \u0648\u0643\u0644\u0627\u0621 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a: \u0632\u0627\u062d\u0641 \u0622\u0645\u0646\u060c \u0646\u062d\u0648 60 \u0641\u062d\u0635\u0627\u064b\u060c \u062a\u0646\u0642\u064a\u0637 \u0645\u0631\u062c\u0651\u062d \u0639\u0644\u0649 8 \u0641\u0626\u0627\u062a\u060c \u062a\u0642\u0631\u064a\u0631 PDF \u0648\u0634\u0631\u0648\u062d\u0627\u062a LLM \u0627\u062e\u062a\u064a\u0627\u0631\u064a\u0629."}, "tags": ["FastAPI", "Next.js", "TypeScript", "PostgreSQL", "Celery"], "image": "/assets/images/project_ai_auditor_3d_light_1793556805441.jpg", "github": "https://github.com/abdertalibi-gif/Agent_readiness_auditor", "demo": "", "published": true, "featured": true, "order": 2, "createdAt": "2026-11-21T11:56:43.949Z", "updatedAt": "2026-11-21T11:56:43.949Z"}, {"id": "proj-robot-simulator", "title": {"en": "Mobile Robot Simulator", "fr": "Simulation de robot mobile", "de": "Simulation eines mobilen Roboters", "ar": "\u0645\u062d\u0627\u0643\u0627\u0629 \u0631\u0648\u0628\u0648\u062a \u0645\u062a\u0646\u0642\u0644"}, "description": {"en": "Differential-drive robot simulator: kinematic engine in TypeScript, real-time telemetry, autonomous obstacle avoidance and navigation scenarios (.obs/.pts) with JSON/CSV export.", "fr": "Simulateur de robot mobile diff\u00e9rentiel : moteur cin\u00e9matique en TypeScript, t\u00e9l\u00e9m\u00e9trie temps r\u00e9el, \u00e9vitement d''obstacles autonome et sc\u00e9narios de navigation (.obs/.pts), export JSON/CSV.", "de": "Simulator f\u00fcr einen differentiellen mobilen Roboter: kinematische Engine in TypeScript, Echtzeit-Telemetrie, autonome Hindernisvermeidung und Navigationsszenarien (.obs/.pts) mit JSON/CSV-Export.", "ar": "\u0645\u062d\u0627\u0643\u064a \u0631\u0648\u0628\u0648\u062a \u0645\u062a\u0646\u0642\u0644 \u062a\u0641\u0627\u0636\u0644\u064a: \u0645\u062d\u0631\u0643 \u062d\u0631\u0643\u064a \u0628\u0644\u063a\u0629 TypeScript\u060c \u0642\u064a\u0627\u0633 \u0639\u0646 \u0628\u064f\u0639\u062f \u0641\u0648\u0631\u064a\u060c \u062a\u062c\u0646\u0628 \u062a\u0644\u0642\u0627\u0626\u064a \u0644\u0644\u0639\u0648\u0627\u0626\u0642 \u0648\u0633\u064a\u0646\u0627\u0631\u064a\u0648\u0647\u0627\u062a \u062a\u0646\u0642\u0644 (.obs/.pts) \u0645\u0639 \u062a\u0635\u062f\u064a\u0631 JSON/CSV."}, "tags": ["React", "TypeScript", "Vite", "Simulation"], "image": "/assets/images/project_robot_vision_3d_light_1793556806282.jpg", "github": "https://github.com/abdertalibi-gif/robotique", "demo": "", "published": true, "featured": false, "order": 3, "createdAt": "2026-11-21T11:56:43.949Z", "updatedAt": "2026-11-21T11:56:43.949Z"}], "skillCategories": [{"id": "cat-backend", "key": "backend", "name": {"en": "Backend Development", "fr": "D\u00e9veloppement Backend", "de": "Backend-Entwicklung", "ar": "\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u062e\u0644\u0641\u064a\u0629"}, "order": 1}, {"id": "cat-frontend", "key": "frontend", "name": {"en": "Frontend & Mobile", "fr": "Frontend & Mobile", "de": "Frontend & Mobile", "ar": "\u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0623\u0645\u0627\u0645\u064a\u0629 \u0648\u0627\u0644\u062c\u0648\u0627\u0644"}, "order": 2}, {"id": "cat-database", "key": "database", "name": {"en":